def moving_average(values, window):
    """Yield the average of each run of `window` consecutive values."""
    if window <= 0:
        raise ValueError("window must be positive")
    total = 0.0
    buffer = []
    for value in values:
        buffer.append(value)
        total += value
        if len(buffer) > window:
            total -= buffer.pop(0)
        if len(buffer) == window:
            yield total / window


